import styled from '@emotion/styled';

export const FooterActions = styled.div({
  display: 'flex',
  flexDirection: 'row',
  justifyContent: 'space-between',
  alignItems: 'center',
  gap: '12px',
  flexGrow: '1',
  height: '40px',
});

export const TriggerButton = styled.div({
  alignItems: 'center',
  backgroundColor: '#ffffff',
  border: '1px solid #1414141f',
  borderRadius: '24px',
  boxShadow: 'none',
  boxSizing: 'border-box',
  color: '#141414',
  cursor: 'pointer',
  display: 'flex',
  flexWrap: 'wrap',
  fontFamily: 'Work Sans',
  fontSize: '16px',
  fontWeight: '500',
  justifyContent: 'space-between',
  minHeight: '40px',
  outline: '0 !important',
  padding: '0 12px 0 8px',
  position: 'relative',
  transition: '100ms',
  width: '100%',

  '&:focus-visible': {
    outline: '2px solid #006edb !important',
    outlineOffset: '2px',
  },
});

export const TriggerValueContainer = styled.div({
  alignItems: 'center',
  display: 'flex',
  flex: 1,
  flexWrap: 'wrap',
  gap: '4px',
  overflow: 'hidden',
  padding: '2px 8px',
  position: 'relative',
});

export const TriggerLabel = styled.span({
  color: '#141414',
  fontWeight: 500,
});

export const TriggerChipValue = styled.span({
  marginLeft: '2px',
  marginRight: '7px',
  maxWidth: '100%',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
});

export const TriggerIcon = styled.span({
  color: '#6b7280',
  display: 'inline-flex',
  alignItems: 'center',
  padding: '0 8px',
});
